bool found = false;
for (uint256 i = 0; i < _owners.length; i++) {
if (_owners[i] == ownerToRemove) {
_owners[i] = _owners[_owners.length - 1];
_owners.pop();
found = true;
emit OwnerRemoved(ownerToRemove);
break;
}
}
if (!found) {
revert OwnableInvalidOwner(ownerToRemove);
}
}

